import math

state = {
    'prev_hitch': 0.0,
    'turn_dir': 0,
}

def control(obs):
    look_deg = -23.0
    views = obs.get('views', {})

    wall_pts = []
    for vname in ['camera', 'direct', 'periphery']:
        v = views.get(vname)
        if not v:
            continue
        ox, oy = v['origin']
        for pt in v.get('walls', []):
            b_deg, dist = pt[0], pt[1]
            rad = math.radians(b_deg)
            wx = ox + dist * math.cos(rad)
            wy = oy + dist * math.sin(rad)
            wall_pts.append((wx, wy))

    tr_x, tr_y = obs['rig']['trailer_rear']
    psi_t = obs['rig']['trailer_heading_deg']
    hitch = obs.get('hitch_deg', 0.0)
    rem = obs.get('progress', {}).get('remaining', 30.0)

    cos_a = math.cos(math.radians(psi_t))
    sin_a = math.sin(math.radians(psi_t))

    pts_tb = []
    for wx, wy in wall_pts:
        dx = wx - tr_x
        dy = wy - tr_y
        xtb = -dx * cos_a - dy * sin_a
        ytb = -dx * sin_a + dy * cos_a
        pts_tb.append((xtb, ytb))

    lefts = [y for x, y in pts_tb if 1.0 <= x <= 4.5 and 0.3 < y < 3.5]
    rights = [y for x, y in pts_tb if 1.0 <= x <= 4.5 and -3.5 < y < -0.3]
    blockers = [x for x, y in pts_tb if 0.5 <= x <= 4.0 and abs(y) < 1.0]

    tgt = obs.get('target', {})
    tgt_ytb = None
    if tgt.get('in_sight') and tgt.get('dist_m') is not None:
        b_rad = math.radians(tgt['bearing_deg'])
        d_tgt = tgt['dist_m']
        tx = 1.62 + d_tgt * math.cos(b_rad)
        ty = 0.41 + d_tgt * math.sin(b_rad)
        dx = tx - tr_x
        dy = ty - tr_y
        xtb_tgt = -dx * cos_a - dy * sin_a
        tgt_ytb = -dx * sin_a + dy * cos_a
        if xtb_tgt > 0:
            if tgt_ytb > 0.5:
                state['turn_dir'] = 1
            elif tgt_ytb < -0.5:
                state['turn_dir'] = -1

    if blockers:
        min_blk = min(blockers)
        if min_blk < 3.5:
            if state['turn_dir'] == 0:
                if rights and not lefts:
                    state['turn_dir'] = 1
                elif lefts and not rights:
                    state['turn_dir'] = -1
                elif lefts and rights:
                    state['turn_dir'] = 1 if max(rights) > -1.2 else -1
                else:
                    state['turn_dir'] = 1

    y_target = 0.0
    if rem < 2.5:
        y_target = 0.0
    elif rem < 6.0 and tgt_ytb is not None:
        y_target = tgt_ytb
    elif blockers and min(blockers) < 3.2:
        y_target = 1.6 if state['turn_dir'] == 1 else -1.6
    else:
        y_L = min(lefts) if lefts else None
        y_R = max(rights) if rights else None
        if y_L is not None and y_R is not None:
            y_target = (y_L + y_R) / 2.0
        elif y_R is not None:
            y_target = y_R + 1.85
        elif y_L is not None:
            y_target = y_L - 1.85
        else:
            y_target = 0.0

    y_target = max(-1.8, min(1.8, y_target))

    if rem < 2.5:
        desired_hitch = 0.0
    else:
        desired_hitch = y_target * 16.0

    MAX_HITCH = 16.0
    desired_hitch = max(-MAX_HITCH, min(MAX_HITCH, desired_hitch))

    dt = obs.get('dt', 0.1)
    if dt <= 0:
        dt = 0.1
    hitch_rate = (hitch - state['prev_hitch']) / dt
    state['prev_hitch'] = hitch

    err = hitch - desired_hitch
    steer = 2.4 * err + 0.8 * hitch_rate
    steer = max(-33.0, min(33.0, steer))

    if rem < 1.0:
        speed = -0.3
    elif rem < 3.0:
        speed = -0.6
    elif abs(hitch) > 12.0:
        speed = -0.7
    else:
        speed = -1.0

    return (steer, speed, look_deg)

